  const hits=fields.interests.filter(t=>agentInterestHit(t,p));
  rationale.push({decision:'选择：'+p.name,reason:hits.length?'匹配你的兴趣（'+hits.map(t=>AGENT_INTEREST_LABELS[t]).join('、')+'）':'同城顺路，用于补足 '+fields.days+' 天行程'});
