  if(!allowed.length)agentError('该城市暂无可规划的目录地点，请在地图中选点');
  for(const id of intent.requiredIds)if(!allowed.some(p=>p.id===id))agentError('必去地点不在当前城市可规划目录内，请核对开放状态、排除条件或选择河南多城');
